#![allow(clippy::expect_used, clippy::unwrap_used, clippy::panic)]
// SPDX-License-Identifier: Apache-2.0
//! T4's `items.window` against `vectors/item-window.json`, generated by
//! `vectors/make-item-window-vectors.ts` from a real Store. The fixture carries the six item
//! tables and the long-thread index (`long_items`, `long_turns`) plus `itemsWindow`'s answers
//! for a window around a sequence, the newest, an item id, a missing id, a turn ordinal and
//! `wholeTurns`; the Rust read must give the same bytes through the same schema.

use std::sync::Arc;

use ace_json::Value;
use ace_store::reads::item_window::{
    ItemWindowRequest, WINDOW_BYTES, WindowError, WindowTarget, items_window,
};
use ace_store::reads::stored::trusted_from;
use ace_store::{Connection, OpenOptions};

fn vectors() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/vectors/item-window.json");
    let text = std::fs::read_to_string(path).expect("read item-window.json");
    ace_json::parse(&text).expect("parse item-window.json")
}

fn array<'a>(value: &'a Value, key: &str) -> &'a [Value] {
    match value.get(key) {
        Some(Value::Array(items)) => items,
        _ => panic!("{key} is not an array"),
    }
}

fn text(value: &Value, key: &str) -> String {
    match value.get(key) {
        Some(Value::String(seen)) => seen.as_str().to_owned(),
        _ => panic!("{key} is not a string"),
    }
}

fn optional_number(value: &Value, key: &str) -> Option<u64> {
    match value.get(key) {
        Some(Value::Number(seen)) => Some(seen.value() as u64),
        _ => None,
    }
}

fn strings(value: &Value, key: &str) -> Vec<String> {
    array(value, key)
        .iter()
        .map(|entry| match entry {
            Value::String(seen) => seen.as_str().to_owned(),
            _ => panic!("{key} holds a non-string"),
        })
        .collect()
}

fn database(vectors: &Value) -> Arc<Connection> {
    let conn = Connection::open(
        ":memory:",
        OpenOptions {
            read_only: false,
            timeout_ms: 0,
        },
    )
    .expect("open in-memory store");
    conn.exec("PRAGMA foreign_keys = OFF")
        .expect("foreign keys off");
    for statement in strings(vectors, "schema") {
        conn.exec(&statement).expect("create schema");
    }
    for statement in strings(vectors, "inserts") {
        conn.exec(&statement).expect("insert fixture row");
    }
    conn
}

fn request_of(case: &Value) -> ItemWindowRequest {
    let query = match case.get("query") {
        Some(Value::String(seen)) => ace_json::parse(seen.as_str()).expect("parse query"),
        _ => panic!("query"),
    };
    let target = if let Some(seq) = optional_number(&query, "aroundSeq") {
        WindowTarget::Around(seq)
    } else if let Some(item) = query.get("itemId").and_then(|item| match item {
        Value::String(seen) => Some(seen.as_str().to_owned()),
        _ => None,
    }) {
        WindowTarget::Item(item)
    } else if let Some(ordinal) = optional_number(&query, "turnOrdinal") {
        WindowTarget::Turn(ordinal)
    } else {
        panic!("a window without a target")
    };
    ItemWindowRequest {
        thread_id: text(case, "threadId"),
        target,
        before: optional_number(&query, "before")
            .map(|value| value as usize)
            .unwrap_or(50),
        after: optional_number(&query, "after")
            .map(|value| value as usize)
            .unwrap_or(50),
        byte_limit: WINDOW_BYTES,
        whole_turns: matches!(query.get("wholeTurns"), Some(Value::Bool(true))),
    }
}

/// Every window is the TypeScript's bytes, or its failure.
#[test]
fn every_window_is_the_typescripts() {
    let vectors = vectors();
    let conn = database(&vectors);
    for case in array(&vectors, "cases") {
        let name = text(case, "name");
        let request = request_of(case);
        let result = items_window(conn.clone(), &request, &trusted_from(0));
        match case.get("error") {
            Some(Value::String(error)) => {
                assert_eq!(result, Err(WindowError::TurnUnavailable), "{name}: {error}");
            }
            _ => {
                let window = result.unwrap_or_else(|error| panic!("{name}: {error:?}"));
                assert_eq!(
                    ace_json::to_string(&window.to_value(&request.thread_id)),
                    text(case, "expected"),
                    "{name}"
                );
            }
        }
    }
}
